"""Ad-hoc verification: LordSiva Nerd Font Propo installation & kitty config."""
import subprocess, sys, os

errors = []

# 1. Check font files in ~/.fonts
fonts_dir = os.path.expanduser("~/.fonts")
expected = ["Regular", "Bold", "Italic", "BoldItalic"]
for style in expected:
    path = os.path.join(fonts_dir, f"LordSivaNerdFontPropo-{style}.ttf")
    if os.path.isfile(path):
        print(f"  ✅ File present: LordSivaNerdFontPropo-{style}.ttf")
    else:
        errors.append(f"Missing font file: {path}")
        print(f"  ❌ Missing: LordSivaNerdFontPropo-{style}.ttf")

# 2. Check fc-list
try:
    out = subprocess.run(["fc-list", "--format=%{family[0]}\n"], capture_output=True, text=True)
    families = set(out.stdout.strip().split("\n"))
    if "LordSiva Nerd Font Propo" in families:
        print("  ✅ fc-list sees 'LordSiva Nerd Font Propo'")
    else:
        errors.append("Font family not found in fc-list")
        print("  ❌ fc-list does not show LordSiva Nerd Font Propo")
except Exception as e:
    errors.append(f"fc-list failed: {e}")
    print(f"  ❌ fc-list error: {e}")

# 3. Check fc-match resolves
try:
    out = subprocess.run(["fc-match", "LordSiva Nerd Font Propo"], capture_output=True, text=True)
    if "LordSivaNerdFontPropo" in out.stdout:
        print(f"  ✅ fc-match resolves: {out.stdout.strip()}")
    else:
        errors.append(f"fc-match did not resolve to LordSiva: {out.stdout.strip()}")
        print(f"  ❌ fc-match: {out.stdout.strip()}")
except Exception as e:
    errors.append(f"fc-match failed: {e}")
    print(f"  ❌ fc-match error: {e}")

# 4. Check kitty.conf has the font block
kitty_conf = os.path.expanduser("~/.config/kitty/kitty.conf")
if os.path.isfile(kitty_conf):
    with open(kitty_conf) as f:
        content = f.read()
    if 'family="LordSiva Nerd Font Propo"' in content:
        print("  ✅ kitty.conf contains the LordSiva font block")
    else:
        errors.append("kitty.conf missing LordSiva font block")
        print("  ❌ kitty.conf does not have LordSiva font block")
else:
    errors.append("kitty.conf not found")
    print("  ❌ kitty.conf not found")

# Summary
print()
if errors:
    print(f"❌ VERIFICATION FAILED — {len(errors)} issue(s):")
    for e in errors:
        print(f"   - {e}")
    sys.exit(1)
else:
    print("✅ VERIFICATION PASSED — All checks OK")
    print("   Note: final visual verification requires Kitty reload (Ctrl+Shift+F5)")
"}

