import os, subprocess, sys
from fontTools.ttLib import TTFont

errors = []
fonts = os.path.expanduser('~/.fonts')

for style in ['Regular','Italic','Bold','BoldItalic']:
    p = os.path.join(fonts, f'LordSivaNerdFontPropo-{style}.ttf')
    if not os.path.isfile(p):
        errors.append(f'Missing {style}')
        continue
    tt = TTFont(p)
    for r in tt['name'].names:
        if r.nameID==1 and r.platformID==1:
            if r.langID != 0:
                errors.append(f'{style}: Mac langID={r.langID}')
            if r.toUnicode() != 'LordSiva Nerd Font Propo':
                errors.append(f'{style}: family={r.toUnicode()!r}')
    tt.close()

conf = os.path.expanduser('~/.config/kitty/kitty.conf')
with open(conf) as f:
    c = f.read()
if 'font_family      LordSiva Nerd Font Propo' not in c:
    errors.append('kitty.conf missing font directive')

out = subprocess.run(['fc-list','--format=%{family[0]}\n'], capture_output=True, text=True)
if 'LordSiva Nerd Font Propo' not in out.stdout:
    errors.append('fc-list missing font')

if errors:
    print('FAILED: ' + '; '.join(errors))
    sys.exit(1)
else:
    print('PASSED — all checks ok')
""}

